//go:build riscv64

package floats

// RVV 1.0 Maximum and Minimum kernels (maxmin.go, gated on hasRVV,
// kernels_riscv64.go), generated by go-asmgen (maxmin_riscv64_gen.go) into
// maxmin_riscv64.s. They are vector-length agnostic: no scalar tail.
//
//go:noescape
func maximumRVV(dst, a, b *float64, n int)

//go:noescape
func minimumRVV(dst, a, b *float64, n int)

func vmaximum(dst, a, b []float64) {
	if len(a) == 0 || !hasRVV {
		maximumRef(dst, a, b)
		return
	}
	maximumRVV(&dst[0], &a[0], &b[0], len(a))
}

func vminimum(dst, a, b []float64) {
	if len(a) == 0 || !hasRVV {
		minimumRef(dst, a, b)
		return
	}
	minimumRVV(&dst[0], &a[0], &b[0], len(a))
}
